const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/taskloc";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "loc.test.mjs"), [
  "import { test } from 'vitest'",
  "",
  "test('adds', () => {})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--reporter=verbose", "--includeTaskLocation"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
const out = (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "");
console.log(out);
const m = out.match(/loc\.test\.mjs:(\d+)(:\d+)? > adds/);
if (!m || m[1] !== "3") {
  console.error("ERROR: no location loc.test.mjs:3 for test adds in output (exit " + r.status + ")");
  process.exit(2);
}
if (m[2]) {
  console.error("FAIL: --includeTaskLocation printed the column after the line number");
  process.exit(1);
}
if (r.status !== 0) {
  console.error("ERROR: vitest exited " + r.status);
  process.exit(2);
}
console.log("PASS: --includeTaskLocation printed only the line: " + m[0]);
process.exit(0);

